shell.powershell:
$module = Join-Path $PikoPackageRoot 'PSFzf.psd1'
$loaded = Get-Module PSFzf
if ($loaded -and ($loaded.ModuleBase -ne $PikoPackageRoot)) { throw 'Another PSFzf module is already loaded; open a clean Shell.' }
$oldPath = $env:PATH
try {
  $env:PATH = (Split-Path $PikoDependencies['fzf']) + ';' + $oldPath
  Import-Module $module -Global -ErrorAction Stop
} finally { $env:PATH = $oldPath }
